// spec: specs/guides-videos.md (2.1–2.4) · кейсы: .qa/tests/guides-videos/GUIDES-22.md, GUIDES-23.md
// seed: tests/seed.spec.ts (гость, без storageState) · прод, только чтение: не-GET обрываются, SW выключен.
// Тикет #359741 «מה רצוי»: «להסתיר את המדריכים מכל המשתמשים. רק מנהל (admin) יכול לראות אותם… מי שאינו מנהל ונכנס
// ל-/guides בקישור ישיר לא יראה את העמוד». Способ — редирект на главную (комментарий программиста, PR #203).
// Файлы /guides/*.mp4 здесь не проверяются (не требование тикета).
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, LOAD, NAV, GUIDES_LINKS, DIRECT_GUIDES_URLS, dismissPopups, openMobileMenu, expectNoGuidesContent,
  linkTexts, expectNext, CALC, PUBLISH, FAQ,
} from './guides.helpers';

test.use({ storageState: { cookies: [], origins: [] }, serviceWorkers: 'block' });

test.describe('Гайды скрыты — гость (#359741)', () => {
  test('гость: в шапке и футере нет ссылок на гайды, за калькулятором — «פרסום עסק למכירה» / «שאלות ותשובות» #359741 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/');
    const banner = page.getByRole('banner');
    await expect(banner.getByRole('button', { name: 'התחברות' }), 'гость: кнопка «התחברות» в шапке').toBeVisible(LOAD);
    await expect(banner.getByRole('link', { name: CALC, exact: true }), 'шапка отрисована').toBeVisible(LOAD);

    await expect(banner.locator(GUIDES_LINKS), 'в шапке нет ссылок на /guides').toHaveCount(0);
    await expect(banner.getByRole('link', { name: /מדריכ/ }), 'в шапке нет пункта «מדריכים»').toHaveCount(0);
    expectNext(await linkTexts(banner), CALC, PUBLISH, 'шапка');

    const footer = page.getByRole('contentinfo');
    await expect(footer.getByRole('link', { name: FAQ, exact: true }), 'футер отрисован').toBeVisible(LOAD);
    await expect(footer.locator(GUIDES_LINKS), 'в футере нет ссылок на /guides').toHaveCount(0);
    await expect(footer.getByRole('link', { name: /מדריכ/ }), 'в футере нет «מדריכי וידאו»').toHaveCount(0);
    expectNext(await linkTexts(footer), CALC, FAQ, 'футер');

    await expect(page.locator(GUIDES_LINKS), 'на всей странице нет ссылок на /guides').toHaveCount(0);
  });

  test('гость: в мобильном меню «תפריט» и футере нет ссылок на гайды, 4-й пункт — калькулятор, 5-й — «פרסום עסק למכירה» #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/');
    const menu = await openMobileMenu(page);
    await expect(menu.locator(GUIDES_LINKS), 'в меню нет ссылок на /guides').toHaveCount(0);
    await expect(menu.getByRole('link', { name: /מדריכ/ }), 'в меню нет «מדריכים»').toHaveCount(0);
    const items = menu.getByRole('link');
    await expect(items.nth(3), '4-й пункт').toHaveText(CALC);
    await expect(items.nth(4), '5-й пункт').toHaveText(PUBLISH);

    await page.keyboard.press('Escape');
    await expect(menu, 'меню закрыто').toBeHidden();
    const footer = page.getByRole('contentinfo');
    await expect(footer.getByRole('link', { name: FAQ, exact: true }), 'футер отрисован').toBeAttached(LOAD);
    await expect(footer.locator(GUIDES_LINKS), 'в футере нет ссылок на /guides').toHaveCount(0);
  });

  for (const url of DIRECT_GUIDES_URLS) {
    test(`гость: прямой ${url} → главная без контента гайдов, «назад» возвращает на прошлую страницу #359741 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await dismissPopups(page);
      await page.goto('/calculator');
      await expect(page.locator('#calc-purchasePrice'), '/calculator открыт').toBeVisible(LOAD);

      await page.goto(url);
      await page.waitForURL((u) => u.pathname === '/', NAV);
      await expect(page.getByRole('link', { name: 'צפה בכל העסקים' }).first(), 'открыта главная').toBeVisible(LOAD);
      await expectNoGuidesContent(page, url);

      await page.goBack();
      await page.waitForURL((u) => u.pathname === '/calculator', NAV);
      await expect(page, '«назад» не возвращает на /guides (запись истории заменена)').not.toHaveURL(/guides/i);
    });
  }

  test('гость: прямой /guides на телефоне → главная без контента гайдов #359741 @mobile @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await dismissPopups(page);
    await page.goto('/guides');
    await page.waitForURL((u) => u.pathname === '/', NAV);
    await expect(page.getByRole('link', { name: 'צפה בכל העסקים' }).first(), 'главная отрисована').toBeVisible(LOAD);
    await expectNoGuidesContent(page, '/guides (mobile)');
  });
});
